def _serialize_trade_row(t: dict, names: dict[str, str]) -> dict[str, Any]:
    sym = t.get("symbol") or "—"
    return {
        "timestamp": t.get("timestamp") or "—",
        "type": t.get("type") or "—",
        "symbol": sym,
        "name": display_name(str(sym), names),
        "quantity": float(t.get("quantity") or 0),
        "price": float(t.get("price") or 0),
        "commission": float(t.get("commission") or 0),
        "profit_loss": t.get("profit_loss"),
        "profit_loss_pct": t.get("profit_loss_pct"),
        "strategy": t.get("strategy"),
        "note": t.get("note"),
        "score": t.get("score"),
        "confidence": t.get("confidence"),
        "source": t.get("source"),
        "exit_reason": t.get("exit_reason"),
        "total_cost": t.get("total_cost"),
        "cash_remaining": t.get("cash_remaining"),
    }


def _parse_book_ts(raw: Any) -> Optional[datetime]:
    """Parse portfolio reset_at or trade timestamp into aware UTC."""
    if raw is None:
        return None
    text = str(raw).strip()
    if not text:
        return None
    # ISO with optional Z
    try:
        iso = text.replace("Z", "+00:00") if text.endswith("Z") else text
        dt = datetime.fromisoformat(iso)
        if dt.tzinfo is None:
            return dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)
    except ValueError:
        pass
    for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%d"):
        try:
            return datetime.strptime(text[:19] if len(text) >= 19 else text, fmt).replace(
                tzinfo=timezone.utc
            )
        except ValueError:
            continue
    return None


def book_start_meta(
    portfolio: dict,
    trades: list[dict],
    *,
    now: Optional[datetime] = None,
) -> dict[str, Any]:
    """Book start date + age for Overview (reset_at, else first fill)."""
    start = _parse_book_ts(portfolio.get("reset_at"))
    if start is None:
        for t in trades:
            cand = _parse_book_ts(t.get("timestamp"))
            if cand is not None:
                start = cand
                break
    if start is None:
        return {
            "book_start": "",
            "book_age_days": None,
            "book_age_label": "",
        }
    clock = now or datetime.now(timezone.utc)
    if clock.tzinfo is None:
        clock = clock.replace(tzinfo=timezone.utc)
    days = max(0, (clock.date() - start.astimezone(timezone.utc).date()).days)
    date_s = start.strftime("%Y-%m-%d")
    return {
        "book_start": date_s,
        "book_age_days": days,
        "book_age_label": f"{date_s} ({days}d)",
    }



def _format_age_short(age_sec: float) -> str:
    """Human age for scan freshness (display only)."""
    sec = max(0, int(age_sec))
    if sec < 60:
        return "just now"
    if sec < 3600:
        return f"{sec // 60}m ago"
    if sec < 36 * 3600:
        return f"{sec // 3600}h ago"
    return f"{sec // 86400}d ago"


# Last cash close vs now (display only). Fresh <12h same-evening print;
# aging <36h through next session / Saturday; else weekend/missed-session stale.
CASH_PRINT_FRESH_HOURS = 12
CASH_PRINT_AGING_HOURS = 36


def cash_print_freshness(age_sec: float) -> str:
    """RyanJHamby fresh/aging/stale for a pinned cash print (display only)."""
    age = max(0.0, float(age_sec))
    if age < CASH_PRINT_FRESH_HOURS * 3600:
        return "fresh"
    if age < CASH_PRINT_AGING_HOURS * 3600:
        return "aging"
    return "stale"


def _scan_last_published_provenance(
    clock: datetime,
) -> tuple[str, str, dict[str, Any]]:
    """xang1234 last-published / market-pointer honesty (display only).

    Composite scan age is not a per-market live quote. When US or Xetra cash
    is closed (or weekend stocks paused), speak last-published so a fresh
    crypto tick is not treated as a live equity snapshot. Mixed sessions
    name each sleeve live vs last-published (xang1234 compile-path). Crypto
    is 24/7, so a pinned cash compile still has a live crypto sleeve — name
    it when cash is not fully open. Closed sleeves also speak hours since
    that venue's last cash close plus a freshness band (pinned print age ≠
    scan archive age; hours alone hid weekend vs same-evening). Both cash
    sleeves open stays silent. Not an entry gate; we do not store separate
    per-market scan files.
    """
    from stock_checker.market_hours import (
        is_us_cash_session_closed,
        is_xetra_session_closed,
        last_us_cash_session_close,
        last_xetra_session_close,
    )

    extra: dict[str, Any] = {
        "cash_print_us_age_sec": None,
        "cash_print_us_freshness": "",
        "cash_print_us_last_published": False,
        "cash_print_xetra_age_sec": None,
        "cash_print_xetra_freshness": "",
        "cash_print_xetra_last_published": False,
    }

    def _print_bits(close_at: datetime) -> tuple[str, str, int]:
        utc_now = clock.astimezone(timezone.utc)
        closed = close_at.astimezone(timezone.utc)
        age_sec = max(0, int((utc_now - closed).total_seconds()))
        band = cash_print_freshness(float(age_sec))
        label = _format_age_short(float(age_sec))
        return f"{label} · {band}", band, age_sec

    utc = clock.astimezone(timezone.utc)
    us_bit, us_band, us_age = _print_bits(last_us_cash_session_close(now=clock))
    xetra_bit, xetra_band, xetra_age = _print_bits(
        last_xetra_session_close(now=clock)
    )
    extra["cash_print_us_age_sec"] = us_age
    extra["cash_print_us_freshness"] = us_band
    extra["cash_print_xetra_age_sec"] = xetra_age
    extra["cash_print_xetra_freshness"] = xetra_band
    if utc.weekday() >= 5:
        extra["cash_print_us_last_published"] = True
        extra["cash_print_xetra_last_published"] = True
        return (
            "last_published",
            "last published · stocks paused · "
            f"US {us_bit} · Xetra {xetra_bit} · crypto live",
            extra,
        )
    us_closed = bool(is_us_cash_session_closed(now=clock))
    xetra_closed = bool(is_xetra_session_closed(now=clock))
    extra["cash_print_us_last_published"] = us_closed
    extra["cash_print_xetra_last_published"] = xetra_closed
    if not us_closed and not xetra_closed:
        return "live", "", extra
    if us_closed and xetra_closed:
        return (
            "last_published",
            "last published · US closed · "
            f"{us_bit} · Xetra closed · {xetra_bit} · crypto live",
            extra,
        )
    us_line = f"US last-published · {us_bit}" if us_closed else "US live"
    xetra_line = (
        f"Xetra last-published · {xetra_bit}" if xetra_closed else "Xetra live"
    )
    return "mixed", f"compile mixed · {us_line} · {xetra_line} · crypto live", extra


_CASH_PRINT_RANK = {"fresh": 0, "aging": 1, "stale": 2}


def _scan_vs_cash_print_clash(
    tone: str, meta: Mapping[str, Any]
) -> tuple[str, str, str]:
    """xang1234 compile clock vs pinned print (display only).

    A fresh 10m scan archive is the crypto/composite clock, not a live cash
    print. Speak when that archive tone disagrees with the worst last-published
    sleeve. Same band stays silent. Live cash stays silent.

    When sleeves disagree on band (or only one is pinned), name the market
    that owns the worst print — xang1234 #531 market-pointer over a nameless
    global ``cash`` label. Both sleeves on the same worst band stay ``cash``.
    When a market-pointer owns the worst print and the other pinned sleeve is
    calmer, also speak that runner band (portfolio AI speak-both-sides) so
    friends see US stale · Xetra aging, not a lone worst label. Naming both
    bands is not the gap: return the runner band so the desk can speak
    ``sleeve Δ wide|thin`` (xang1234 share-Δ after speak-both-sides).
    """
    if tone not in _CASH_PRINT_RANK:
        return "", "", ""
    sleeves: list[tuple[str, str]] = []
    if meta.get("cash_print_us_last_published"):
        us_band = str(meta.get("cash_print_us_freshness") or "")
        if us_band in _CASH_PRINT_RANK:
            sleeves.append(("US", us_band))
    if meta.get("cash_print_xetra_last_published"):
        xetra_band = str(meta.get("cash_print_xetra_freshness") or "")
        if xetra_band in _CASH_PRINT_RANK:
            sleeves.append(("Xetra", xetra_band))
    if not sleeves:
        return "", "", ""
    cash = max((band for _, band in sleeves), key=lambda band: _CASH_PRINT_RANK[band])
    if tone == cash:
        return "", cash, ""
    owners = [
        name for name, band in sleeves if _CASH_PRINT_RANK[band] == _CASH_PRINT_RANK[cash]
    ]
    runner_band = ""
    if len(owners) == 1:
        cash_bit = f"{owners[0]} cash {cash}"
        runners = [
            (name, band) for name, band in sleeves if name not in owners
        ]
        if len(runners) == 1:
            r_name, r_band = runners[0]
            cash_bit = f"{cash_bit} · {r_name} {r_band}"
            runner_band = r_band
    else:
        cash_bit = f"cash {cash}"
    return f"scan vs cash clash · scan {tone} · {cash_bit}", cash, runner_band


def _scan_vs_cash_clash_delta(tone: str, cash: str) -> str:
    """xang1234 share-Δ severity after clash (display only).

    Adjacent bands (fresh↔aging, aging↔stale) are Δ thin. Fresh↔stale is
    Δ wide. Same band is silent. Naming the clash alone hid Saturday vs Sunday.
    """
    if tone not in _CASH_PRINT_RANK or cash not in _CASH_PRINT_RANK:
        return ""
    gap = abs(_CASH_PRINT_RANK[tone] - _CASH_PRINT_RANK[cash])
    if gap >= 2:
        return "wide"
    if gap == 1:
        return "thin"
    return ""


def _scan_vs_cash_delta_vs_sleeve(
    clash_delta: str, sleeve_delta: str
) -> tuple[str, bool]:
    """Scan↔cash Δ vs pin sleeve Δ relationship (display only).

    Naming both gaps alone hid whether the compile-clock spread matches the
    worst↔runner pin spread (portfolio AI speak-both-sides after sleeve Δ +
    xang1234 share vs Δ). Same band → ``align · both thin|wide`` (both wide
    warns as adverse dual-wide). Crossed → ``clash · Δ … · sleeve …`` + warn.
    Missing either stays silent.
    """
    a = str(clash_delta or "").strip().casefold()
    b = str(sleeve_delta or "").strip().casefold()
    if a not in ("thin", "wide") or b not in ("thin", "wide"):
        return "", False
    if a == b:
        return f"align · both {a}", a == "wide"
    return f"clash · Δ {a} · sleeve {b}", True


