def cash_print_band_size(meta: Mapping[str, Any] | None, *, clock: str) -> str:
    """Cash pin ring size with venue pointer (display only).

    Scan≠cash, soft≠cash, LAYA/debate ≠ cash (and peer cash) name a
    generation verb. This is the cash sleeve ring (US/Xetra last-published
    on the spoken band) so those clashes are not a nameless sleeve.

    - Sole pin → `` · US-only|Xetra-only`` (xang1234 #647 venue-scope;
      sole ``×1 · 100%`` lied full-cash coverage).
    - Dual pin, one band → `` · US|Xetra · 50%`` (#531 market-pointer;
      nameless ``×1 · 50%`` hid which sleeve owns the half).
    - Dual pin, both on band → `` · ×2 · 100%`` (count≠share).

    Missing pin / band stays silent. Not a gate.
    """
    want = str(clock or "").strip().casefold()
    if want == "expired":
        want = "stale"
    elif want == "unknown":
        want = "fresh"
    if want not in _CASH_PRINT_RANK or not isinstance(meta, Mapping):
        return ""
    sleeves: list[tuple[str, str]] = []
    if meta.get("cash_print_us_last_published"):
        us = str(meta.get("cash_print_us_freshness") or "").strip().casefold()
        if us in _CASH_PRINT_RANK:
            sleeves.append(("US", us))
    if meta.get("cash_print_xetra_last_published"):
        xetra = str(meta.get("cash_print_xetra_freshness") or "").strip().casefold()
        if xetra in _CASH_PRINT_RANK:
            sleeves.append(("Xetra", xetra))
    if not sleeves:
        return ""
    matched = [name for name, band in sleeves if band == want]
    n = len(matched)
    if n <= 0:
        return ""
    if len(sleeves) == 1:
        return f" · {matched[0]}-only"
    share = int(round(100.0 * n / len(sleeves)))
    if n == 1:
        return f" · {matched[0]} · {share}%"
    return f" · ×{n} · {share}%"


def memory_advisory_pin_size(
    *,
    own_clock: str,
    laya_freshness: str = "",
    debate_freshness: str = "",
    matched: bool = False,
) -> str:
    """Advisory pin size with sleeve pointer (display only).

    Soft≠memory and gap≠memory name generation verbs. Soft last-clock
    ``×N`` lied soft coverage was the advisory print; this is the
    LAYA/debate sleeve ring on the clash (cash pin #647 / #531 parity).

    Default (clash): sleeves that *disagree* with ``own_clock``.

    - Sole configured sleeve that clashes → `` · laya-only|debate-only``
    - Dual configured, one clashes → `` · laya|debate · 50%``
    - Dual configured, both clash → `` · ×2 · 100%``

    ``matched=True`` (keep-memory): sleeves that *agree* with
    ``own_clock`` — ride soft≠scan/cash/gap or gap≠scan/cash when
    soft≠memory / gap≠memory is silent so those bits cannot hide the
    advisory match (soft/gap keep-cash · keep-gap · keep-soft speak-
    both-sides + #660 / #647 / #531). Same grammar as clash pins.

    Missing / empty selected stays silent. Not a gate.
    """
    own = str(own_clock or "").strip().casefold()
    if own == "expired":
        own = "stale"
    elif own == "unknown":
        own = "fresh"
    if own not in _CASH_PRINT_RANK:
        return ""

    def _norm(tone: str) -> str:
        t = str(tone or "").strip().casefold()
        if t == "expired":
            return "stale"
        if t == "unknown":
            return "fresh"
        return t if t in _CASH_PRINT_RANK else ""

    sleeves: list[str] = []
    selected: list[str] = []
    for name, raw in (("laya", laya_freshness), ("debate", debate_freshness)):
        t = _norm(raw)
        if not t:
            continue
        sleeves.append(name)
        if matched:
            if t == own:
                selected.append(name)
        elif t != own:
            selected.append(name)
    if not selected:
        return ""
    if len(sleeves) == 1:
        return f" · {selected[0]}-only"
    share = int(round(100.0 * len(selected) / len(sleeves)))
    if len(selected) == 1:
        return f" · {selected[0]} · {share}%"
    return f" · ×{len(selected)} · {share}%"


def memory_vs_cash_clock_clash(
    own_freshness: str, cash_band: str, *, side: str = "soft"
) -> tuple[str, bool]:
    """Memory last vs pinned cash-print generation (display only).

    Returns ``(bit, warn)``. When newest memory clock ≠ worst
    last-published cash sleeve (``expired``≡``stale``), speak
    ``clash · {side} fresh|aging|stale · cash …``. Same band / missing
    either / live cash (no pin) silent. A fresh scan match can still
    hide a staler cash print — closes memory↔cash↔scan with
    memory-vs-scan + scan-vs-cash (xang1234 #549 coherent generations +
    portfolio AI speak-both-sides). Soft-allow + LAYA + AI debate share
    this helper. Not a gate.
    """
    own = str(own_freshness or "").strip().casefold()
    if own == "expired":
        own = "stale"
    elif own == "unknown":
        own = "fresh"
    cash = str(cash_band or "").strip().casefold()
    label = str(side or "soft").strip().casefold() or "soft"
    if own not in _CASH_PRINT_RANK or cash not in _CASH_PRINT_RANK:
        return "", False
    if own == cash:
        return "", False
    return f"clash · {label} {own} · cash {cash}", True


def soft_allow_vs_cash_clock_clash(
    soft_freshness: str, cash_band: str
) -> tuple[str, bool]:
    """Soft-allow last vs pinned cash-print (display only)."""
    return memory_vs_cash_clock_clash(soft_freshness, cash_band, side="soft")


def memory_advisory_clock_tones(
    data_dir: Path | str | None = None,
    *,
    now: Optional[datetime] = None,
    scan_interval_sec: int = 900,
) -> tuple[str, str]:
    """LAYA + AI-debate clock tones for soft-allow generation clash.

    Display only. Empty when no newest stamp. Soft matching the scan
    archive can still hide a staler advisory print (xang1234 #549 +
    FinRobot last-row + portfolio AI speak-both-sides).
    """
    from stock_checker.ai_validate_memory import summarize_ai_debates
    from stock_checker.laya_decision import laya_status

    root = data_dir if data_dir is not None else Path(os.getenv("DATA_DIR", "data"))
    laya_tone = ""
    st = laya_status(root)
    stats = st.get("stats") if isinstance(st.get("stats"), dict) else {}
    newest = stats.get("newest") if isinstance(stats.get("newest"), dict) else None
    laya_at = str((newest or {}).get("at") or "").strip()
    if laya_at:
        pack = build_scan_freshness(
            laya_at, now=now, scan_interval_sec=scan_interval_sec
        )
        laya_tone = str(pack.get("tone") or "")
    debate_tone = ""
    debate_sum = summarize_ai_debates(root)
    debate_at = str(debate_sum.get("latest_at") or "").strip()
    if debate_at:
        pack = build_scan_freshness(
            debate_at, now=now, scan_interval_sec=scan_interval_sec
        )
        debate_tone = str(pack.get("tone") or "")
    return laya_tone, debate_tone


def soft_allow_last_clock_tone(
    data_dir: Path | str | None = None,
    *,
    now: Optional[datetime] = None,
) -> str:
    """Newest soft-allow clock as scan-band tone (display only).

    Maps ``expired``→``stale`` via ``_soft_allow_clock_tone``. Empty when
    the ring has no rows. LAYA/debate matching the scan archive can still
    hide a staler fail-open print — speak-both-sides of soft≠memory
    (xang1234 #549 + FinRobot last-row + portfolio AI). Not a gate.
    """
    from stock_checker.gate_audit import enrich_soft_allows, load_soft_allows

    root = data_dir if data_dir is not None else Path(os.getenv("DATA_DIR", "data"))
    rows = enrich_soft_allows(load_soft_allows(root), now=now)
    if not rows:
        return ""
    last = rows[-1]
    return _soft_allow_clock_tone(str(last.get("freshness") or ""))


