def memory_peer_cash_clock_clash(
    own_freshness: str,
    peer_freshness: str,
    cash_band: str,
    *,
    peer_side: str,
) -> tuple[str, bool]:
    """Peer memory vs cash when own matches cash (display only).

    Returns ``(bit, warn)``. When own clock matches the pinned cash print
    (or own cash clash is silent) but peer ≠ cash, speak
    ``peer cash · {peer} fresh|aging|stale · cash …``. Own already
    clashing stays silent here — the own bit covers it. Matching cash on
    this glance can still hide a peer that disagrees with the cash print
    (LAYA↔debate↔cash triangle; xang1234 #549 / e3c84e1 + FinRobot
    last-row + portfolio AI speak-both-sides). Compact so the 96-char
    clip keeps it beside clock clash. Not a gate.
    """
    own_bit, _ = memory_vs_cash_clock_clash(
        own_freshness, cash_band, side="own"
    )
    if own_bit:
        return "", False
    peer_bit, peer_warn = memory_vs_cash_clock_clash(
        peer_freshness, cash_band, side=peer_side
    )
    if not peer_bit:
        return "", False
    rest = peer_bit.removeprefix("clash · ").strip()
    if not rest:
        return "", False
    return f"peer cash · {rest}", peer_warn


def memory_peer_soft_clock_clash(
    own_freshness: str,
    peer_freshness: str,
    soft_band: str,
    *,
    peer_side: str,
) -> tuple[str, bool]:
    """Peer memory vs soft-allow when own matches soft (display only).

    Returns ``(bit, warn)``. When own clock matches soft-allow (or own soft
    clash is silent) but peer ≠ soft, speak
    ``peer soft · {peer} fresh|aging|stale · soft …``. Own already
    clashing stays silent here — the own bit covers it. Matching soft on
    this glance can still hide a peer that disagrees with the fail-open
    print (LAYA↔debate↔soft triangle; xang1234 #549 / e3c84e1 + FinRobot
    last-row + portfolio AI speak-both-sides). Compact so the 96-char
    clip keeps it beside clock clash. Not a gate.
    """
    soft = str(soft_band or "").strip().casefold()
    if soft == "expired":
        soft = "stale"
    elif soft == "unknown":
        soft = "fresh"
    own = str(own_freshness or "").strip().casefold()
    if own == "expired":
        own = "stale"
    elif own == "unknown":
        own = "fresh"
    peer = str(peer_freshness or "").strip().casefold()
    if peer == "expired":
        peer = "stale"
    elif peer == "unknown":
        peer = "fresh"
    label = str(peer_side or "").strip().casefold() or "peer"
    # Same bands as _CLOCK_FRESH_RANK (defined later); cash rank is local.
    if (
        own not in _CASH_PRINT_RANK
        or peer not in _CASH_PRINT_RANK
        or soft not in _CASH_PRINT_RANK
    ):
        return "", False
    if own != soft:
        return "", False
    if peer == soft:
        return "", False
    return f"peer soft · {label} {peer} · soft {soft}", True


