            sleeve_raw = str(sample.get("sleeve_bit") or "").strip()
            sleeve_core_raw = str(sample.get("sleeve_core_bit") or "").strip()
            sleeve_lean_raw = str(sample.get("sleeve_lean_bit") or "").strip()
